// The visual catalogue: the whole design system on one page for a person who does not read code. Every token (by its
// real name, colours with their contrast on the ground) and every component's stories at phone and desktop width,
// with the card it follows and how far it follows COMPONENTS.md. Regenerated by every visual test. Spec #35.
import { page, esc } from './page.mjs';
import { cropOf, shot } from './before-after.mjs';
import { contrast } from './direction.mjs';

const HEX = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i;
const GROUPS = [['colors', 'Colours'], ['typography', 'Type'], ['spacing', 'Spacing'], ['rounded', 'Corners']];
const SHOWN = ['mobile-390', 'desktop-1280'];

/**
 * @param design      loadDesign() output
 * @param run         the visual test's run.json
 * @param deviations  { Component: number } from the conventions check, or null when no conventions are recorded
 * @param findings    { Component: { count, worst } } open findings, optional
 */
export function renderCatalogue({ design, run, deviations = null, findings = {}, scope = null }) {
  const tokens = Object.values(design.tokens || {}); const files = [];
  const groundToken = design.tokens?.['colors.bg'] || design.tokens?.['colors.background'] || design.tokens?.['colors.surface'];
  const ground = groundToken?.resolved;
  const bg = HEX.test(ground || '') ? ground : '#ffffff';
  const show = (t) => (typeof t.resolved === 'object' ? Object.entries(t.resolved).map(([k, v]) => `${k}: ${v}`).join('; ') : String(t.resolved));
  const tokenHtml = GROUPS.map(([g, title]) => {
    const list = tokens.filter((t) => t.group === g); if (!list.length) return '';
    const item = (t) => {
      if (g === 'colors') return `<div class="sw"><i style="background:${esc(HEX.test(t.resolved) ? t.resolved : 'transparent')}"></i><span><strong>${esc(t.path.slice(7))}</strong> ${esc(t.resolved)}${t === groundToken ? ' · the ground' : HEX.test(t.resolved) ? ` · ${Math.round(contrast(t.resolved, bg) * 10) / 10}:1 on the ground` : ''}<br><code>${esc(t.css)}</code></span></div>`;
      if (g === 'typography') { const v = typeof t.resolved === 'object' ? t.resolved : { fontSize: t.resolved }; return `<div class="ty"><span style="font-family:${esc(v.fontFamily || 'inherit')};font-size:${esc(v.fontSize || '1rem')};font-weight:${esc(v.fontWeight || 400)}">${esc(t.path.slice(11))}</span><code>${esc(t.css)} · ${esc(show(t))}</code></div>`; }
      if (g === 'spacing' && /breakpoint/.test(t.path)) return `<div class="sp"><code>${esc(t.path.slice(8))} · screens ${esc(t.resolved)} and wider · ${esc(t.css)}</code></div>`;
      if (g === 'spacing') return `<div class="sp"><i style="width:${esc(t.resolved)}"></i><code>${esc(t.path.slice(8))} · ${esc(t.resolved)} · ${esc(t.css)}</code></div>`;
      return `<div class="rd"><i style="border-radius:${esc(t.resolved)}"></i><code>${esc(t.path.slice(8))} · ${esc(t.resolved)} · ${esc(t.css)}</code></div>`;
    };
    return `<section class="group"><h3>${title}</h3><div class="items ${g}">${list.map(item).join('')}</div></section>`;
  }).join('');
  const shadows = Object.entries(design.sidecar?.shadows || {});
  const shadowHtml = shadows.length ? `<section class="group"><h3>Shadows</h3><div class="items rounded">${shadows.map(([k, v]) => `<div class="rd"><i style="box-shadow:${esc(v)}"></i><code>${esc(k)} · ${esc(v)}</code></div>`).join('')}</div></section>` : '';

  const byComponent = new Map();
  for (const s of run?.stories || []) { const name = s.title.split('/').pop().trim(); if (!byComponent.has(name)) byComponent.set(name, []); byComponent.get(name).push(s); }
  const inv = (name) => (design.inventory || []).find((c) => c.name.toLowerCase() === name.toLowerCase());
  const compHtml = [...byComponent].map(([name, stories]) => {
    const card = inv(name)?.card;
    const conv = deviations === null ? 'Conventions are not recorded (no COMPONENTS.md).' : deviations[name] ? `${deviations[name]} difference${deviations[name] === 1 ? '' : 's'} from the project's conventions.` : 'Follows the project\'s conventions.';
    const open = findings[name];
    const st = stories.map((s) => `<div class="story"><h4>${esc(s.name)}${s.result === 'failure' ? ' <span class="tag bad">Fails a check</span>' : ''}</h4><div class="shots">${s.captures.filter((c) => SHOWN.includes(c.viewport) && c.screenshot).map((c) => { files.push(c.screenshot); return `<figure>${shot(c.screenshot, `${name} / ${s.name} at ${c.viewport === 'mobile-390' ? '390' : '1280'} wide`, cropOf({ ...c, diff: null }), 1)}<figcaption>${c.viewport === 'mobile-390' ? 'Phone' : 'Desktop'}</figcaption></figure>`; }).join('')}</div></div>`).join('');
    return `<article class="comp" id="c-${esc(name.toLowerCase())}"><header><h3>${esc(name)}</h3><p class="meta">${card ? `Follows the ${esc(card)} card.` : 'No card: the shared rules apply.'} ${esc(conv)}${open ? ` <span class="tag ${open.worst === 'blocking' ? 'bad' : 'warn'}">${open.count} open finding${open.count === 1 ? '' : 's'}</span>` : ''}</p></header>${st}</article>`;
  }).join('');

  const title = `${design.meta?.name || 'Design system'} catalogue`;
  const html = page({
    title,
    css: `main { max-width: 1100px; margin: 0 auto; display: grid; gap: 32px; }
h1 { margin: 0; font-size: 1.5rem; } h2 { margin: 0 0 12px; font-size: 1.25rem; } h3 { margin: 0 0 8px; font-size: 1rem; } h4 { margin: 0 0 6px; font-size: 0.9375rem; font-weight: 600; }
.meta { color: var(--muted); margin: 0; font-size: 0.875rem; }
code { font-size: 0.8125rem; color: var(--muted); overflow-wrap: anywhere; }
.group { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 16px; display: grid; gap: 8px; }
.items { display: grid; gap: 10px; } .items.colors { grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr)); }
.sw { display: flex; gap: 10px; align-items: center; min-width: 0; } .sw i { flex: none; width: 44px; height: 44px; border-radius: 6px; border: 1px solid var(--line); } .sw span { font-size: 0.875rem; min-width: 0; }
.ty { display: grid; gap: 2px; min-width: 0; } .sp { display: grid; gap: 4px; } .sp i { display: block; height: 12px; background: var(--accent); border-radius: 2px; }
.rd { display: flex; gap: 12px; align-items: center; } .rd i { flex: none; width: 56px; height: 40px; background: var(--card); border: 1px solid var(--muted); }
.comp { display: grid; gap: 12px; border-top: 1px solid var(--line); padding-top: 16px; }
.story .shots { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 12px; align-items: start; }
.shots figure { margin: 0; min-width: 0; } figcaption { color: var(--muted); font-size: 0.8125rem; }
.shots img { display: block; max-width: 100%; height: auto; border: 1px solid var(--line); background: #fff; }
.crop { position: relative; overflow: hidden; width: 100%; border: 1px solid var(--line); background: #fff; } .crop img { position: absolute; max-width: none; border: 0; }
.tag { font-size: 0.75rem; font-weight: 600; padding: 1px 8px; border-radius: 999px; border: 1px solid currentColor; } .tag.bad { color: var(--bad); } .tag.warn { color: var(--warn); }`,
    body: `<main>
<header><h1>${esc(title)}</h1><p class="meta">Every token and component, from the visual test of ${esc(String(run?.startedAt || '').replace('T', ' ').slice(0, 16))} UTC. Token names are the ones in the code.${scope ? ` This run covered only ${esc(scope)}: run the visual test with --all for every component.` : ''}</p></header>
<section><h2>Tokens</h2><div style="display:grid;gap:12px">${tokenHtml}${shadowHtml}</div></section>
<section><h2>Components</h2>${compHtml || '<p>No stories yet.</p>'}</section>
</main>`,
  });
  return { html, files: [...new Set(files)] };
}
